-- Disposable empty PostgreSQL database only. No real users or email hooks.
\set ON_ERROR_STOP on
begin;
create schema auth;
create schema private;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
grant usage on schema auth,private to service_role;
create table public.profiles(id uuid primary key,lang text);
create table public.trips(id uuid primary key,traveler_id uuid,from_city text,to_city text,depart_date date);
create table public.parcels(id uuid primary key,sender_id uuid,needed_by date,safety_hold boolean default false);
create table public.matches(id uuid primary key,trip_id uuid,parcel_id uuid,requester_id uuid,status text,updated_at timestamptz);
create table public.parcel_declarations(parcel_id uuid,version int);
create table public.match_inspections(match_id uuid,user_id uuid,declaration_version int,role text);
create table public.match_safety_refusals(match_id uuid);
create table public.reviews(match_id uuid,author_id uuid);
create table public.notification_deliveries(dedup_key text,status text);
create table private.delivery_events(match_id uuid,status text,created_at timestamptz);
create table private.delivery_feedback(match_id uuid,user_id uuid,outcome text);
create table private.delivery_reports(match_id uuid,status text);
\ir ../../supabase/migrations/20261120101420_delivery_return_reminders.sql
create function pg_temp.ok(condition boolean,label text) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
select pg_temp.ok(not has_function_privilege('anon','public.delivery_followup_candidates(uuid)','EXECUTE'),'anonymous users cannot read the queue');
select pg_temp.ok(not has_function_privilege('authenticated','public.delivery_followup_candidates(uuid)','EXECUTE'),'members cannot read the queue');
select pg_temp.ok(not has_function_privilege('authenticated','private.delivery_followup_candidates(uuid)','EXECUTE'),'private queue is also restricted');
select pg_temp.ok(has_function_privilege('service_role','public.delivery_followup_candidates(uuid)','EXECUTE'),'only the worker can read candidates');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into public.profiles values('10000000-0000-4000-8000-000000000001','en'),('20000000-0000-4000-8000-000000000002','fr');
insert into public.trips values('30000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000002','Paris','Nairobi',current_date+2);
insert into public.parcels values('40000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001',current_date+3,false);
insert into public.matches values('50000000-0000-4000-8000-000000000005','30000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001','accepted',now()-interval '23 hours');
select pg_temp.ok((select count(*)=0 from public.delivery_followup_candidates()),'no reminder before 24 hours');
update public.matches set updated_at=now()-interval '25 hours';
select pg_temp.ok((select count(*)=1 and min(stage)='agreement' and min(recipient_id::text)='10000000-0000-4000-8000-000000000001' from public.delivery_followup_candidates()),'agreement reminder targets the requester');
update public.matches set status='escrow_paid';
select pg_temp.ok((select count(*)=1 and min(stage)='contents' from public.delivery_followup_candidates()),'missing declaration asks only the sender');
insert into public.parcel_declarations values('40000000-0000-4000-8000-000000000004',1);
select pg_temp.ok((select count(*)=2 and min(stage)='inspection' from public.delivery_followup_candidates()),'both people have their own inspection');
insert into public.match_inspections values('50000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000001',1,'sender');
select pg_temp.ok((select count(*)=1 and min(recipient_id::text)='20000000-0000-4000-8000-000000000002' from public.delivery_followup_candidates()),'completed sender inspection is not reminded');
insert into public.match_inspections values('50000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000002',1,'traveler');
select pg_temp.ok((select count(*)=1 and min(stage)='collection' from public.delivery_followup_candidates()),'only traveller is asked to confirm collection');
update public.matches set updated_at=now()-interval '60 days';
select pg_temp.ok((select count(*)=1 and min(stage)='collection' from public.delivery_followup_candidates()),'advance bookings still get a handover reminder near departure');
update public.matches set updated_at=now()-interval '25 hours';
update public.parcel_declarations set version=2;
select pg_temp.ok((select count(*)=2 and min(stage)='inspection' from public.delivery_followup_candidates()),'old declaration confirmations never unlock collection');
update public.trips set depart_date=current_date+30;
select pg_temp.ok((select count(*)=0 from public.delivery_followup_candidates()),'no premature handover reminders for distant trips');
update public.matches set status='in_transit';
select pg_temp.ok((select count(*)=0 from public.delivery_followup_candidates()),'no early receipt reminder');
update public.trips set depart_date=current_date-2;
update public.parcels set needed_by=current_date-1;
select pg_temp.ok((select count(*)=1 and min(stage)='receipt' and min(recipient_id::text)='10000000-0000-4000-8000-000000000001' from public.delivery_followup_candidates()),'past arrival date asks only sender about receipt');
insert into private.delivery_reports values('50000000-0000-4000-8000-000000000005','open');
select pg_temp.ok((select count(*)=0 from public.delivery_followup_candidates()),'open complaint blocks reminders');
delete from private.delivery_reports;
insert into private.delivery_feedback values('50000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000001','missing_items');
select pg_temp.ok((select count(*)=0 from public.delivery_followup_candidates()),'partial receipt stops followups too');
delete from private.delivery_feedback;
update public.matches set status='cancelled';
select pg_temp.ok((select count(*)=0 from public.delivery_followup_candidates()),'cancelled delivery is suppressed');
update public.matches set status='released';
select pg_temp.ok((select count(*)=2 and min(stage)='review' from public.delivery_followup_candidates()),'both completed-delivery participants can review');
insert into public.reviews values('50000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000001');
select pg_temp.ok((select count(*)=1 and min(recipient_id::text)='20000000-0000-4000-8000-000000000002' from public.delivery_followup_candidates()),'submitted review stops that person’s reminder');
insert into public.notification_deliveries values('delivery-followup/50000000-0000-4000-8000-000000000005/review/20000000-0000-4000-8000-000000000002','sent');
select pg_temp.ok((select count(*)=0 from public.delivery_followup_candidates()),'sent reminder is not selected again');
update public.notification_deliveries set status='failed';
select pg_temp.ok((select count(*)=1 from public.delivery_followup_candidates()),'failed reminder remains retryable');
update public.matches set updated_at=now()-interval '15 days';
select pg_temp.ok((select count(*)=0 from public.delivery_followup_candidates()),'old backlogs do not generate reminders');
rollback;
